//! Real current-host semantic consumer; no independent AST/model or mock lookup.
use super::*;
use super::super::analysis_context_tests::{checker_fixture as base_fixture,run,current};
fn fixture(source:&str)->(crate::runner_host::BuildHost,crate::request::BuildRequest,std::path::PathBuf){
 let(host,mut request,root)=base_fixture(source);
 // A lexical Windows path is authority only after the recording provider has
 // certified this requested spelling against its actual compiled acquisition.
 request.policy_inputs.as_mut().unwrap().files.push(crate::policy_request::PolicyInputFile{
  path:root.join("code/probe.dm"),role:crate::policy_request::PolicyInputRole::DmSource,required:true,
 });
 request.policy_inputs.as_mut().unwrap().files.push(crate::policy_request::PolicyInputFile{
  path:root.join("code/SpacemanDMM.toml"),role:crate::policy_request::PolicyInputRole::Configuration,required:false,
 });
 (host,request,root)
}
use dm_analysis::checks_undefined_variable::CurrentUndefinedDisposition as Disposition;
use dm_ir::{ResolveQuery,SymbolId};
use dm_query::Kind;
const ABSENT:&str="/datum/receiver\n/proc/probe(datum/receiver/argument)\n    return argument.field\n";
const PRESENT:&str="/datum/receiver\n    var/field\n/proc/probe(datum/receiver/argument)\n    return argument.field\n";
fn observe(host:&crate::runner_host::BuildHost,root:&Path)->(Disposition,Vec<(usize,usize,String)>,usize){current(host,|snapshot|{let archive=snapshot.body_archive.as_ref().unwrap();let dot=archive.expanded_source().find(".field").unwrap_or(0);let mut rows=Vec::new();let disposition=snapshot.visit_current_variable_diagnostics(0,&root.join("code/probe.dm"),None,&snapshot.tree,|row|{rows.push((row.span.start,row.span.end,row.diagnostic.message.clone()));Ok(())}).unwrap();println!("CURRENT_VARIABLE_NATIVE={:?}",(&disposition,&rows,dot));(disposition,rows,dot)})}
fn missing(rows:&[(usize,usize,String)],dot:usize){assert_eq!(rows,&[(dot,dot+1,"undefined field: \"field\" on /datum/receiver".to_owned())]);}
#[test]fn current_variable_actual_negative_lookup_invalidates_on_add_remove_and_unchanged_answers_cut_off_semantics(){
 let(mut host,request,root)=fixture(ABSENT);let queries=host.query_db().clone();run(&mut host,&request);let first=observe(&host,&root);assert_eq!(first.0,Disposition::Evaluated);missing(&first.1,first.2);
 let(parent,lookup,driver,code)=current(&host,|snapshot|{let owner=snapshot.original_checker_request_input(&snapshot.tree).unwrap();let keys=queries.current_variable_keys_for_test(owner.input(),0,ResolveQuery::SourceVarDeclaration{owner:SymbolId::of("/datum/receiver"),name:SymbolId::of("field")});let code=Arc::downgrade(snapshot.body_archive.as_ref().unwrap().syntax_input_checked(0,&||crate::daemon::control::checkpoint()).unwrap().original_code_owner().unwrap());(keys.0,keys.1,keys.2,code)});
 let global_lookup=current(&host,|snapshot|{let owner=snapshot.original_checker_request_input(&snapshot.tree).unwrap();queries.current_variable_keys_for_test(owner.input(),0,ResolveQuery::SourceVarDeclaration{owner:SymbolId::of("/"),name:SymbolId::of("field")}).1});assert!(queries.db().dependants(&[global_lookup]).contains(&parent),"actual absent own variable falls through to a real global absence dependency");
 assert!(queries.db().dependants(&[lookup]).contains(&parent),"the actual missing native declaration answer must be a real parent dependency");assert!(queries.db().dependants(&[driver]).contains(&lookup),"that negative leaf must depend on the actual current model input");let syntax=queries.db().stats(Kind(4)).computed;let semantic=queries.db().stats(Kind(28)).computed;let resolver=queries.db().stats(Kind(29)).computed;
 // A second genuine current syntax consumer borrows the same actual product.
 current(&host,|snapshot|{let archive=snapshot.body_archive.as_ref().unwrap();dm_tree::frontend::SettingExpressionQueries::with_declaration_admission(queries.as_ref(),&mut|admission|archive.with_current_body_checked(0,admission,|body|{let rows=dm_analysis::checks::current_ambiguous_not_bitwise(&body,dm_analysis::checks::Severity::Warning,&||Ok(())).unwrap();assert!(rows.is_empty());Ok(())})).unwrap();});assert_eq!(queries.db().stats(Kind(4)).computed,syntax,"semantic and syntax consumers must share one actual canonical parse");

 std::fs::write(root.join("code/probe.dm"),PRESENT).unwrap();run(&mut host,&request);let present=observe(&host,&root);assert_eq!(present.0,Disposition::Evaluated);assert!(present.1.is_empty());assert!(!queries.db().dependants(&[global_lookup]).contains(&parent),"positive own lookup must retract the unused old global absence edge");assert_eq!(queries.db().stats(Kind(4)).computed,syntax,"field-only change reuses the exact converged canonical BODY");assert_eq!(queries.db().stats(Kind(28)).computed,semantic+1,"actual negative lookup becoming positive must rerun the same semantic producer");assert!(queries.db().stats(Kind(29)).computed>resolver);current(&host,|snapshot|assert!(std::sync::Weak::ptr_eq(&code,&Arc::downgrade(snapshot.body_archive.as_ref().unwrap().syntax_input_checked(0,&||crate::daemon::control::checkpoint()).unwrap().original_code_owner().unwrap()))));
 let unrelated="// α current offset shift\n/datum/receiver\n    var/field\n    var/unrelated\n/proc/probe(datum/receiver/argument)\n    return argument.field\n";std::fs::write(root.join("code/probe.dm"),unrelated).unwrap();run(&mut host,&request);let unchanged=observe(&host,&root);assert!(unchanged.1.is_empty());assert_ne!(present.2,unchanged.2);assert_eq!(queries.db().stats(Kind(28)).computed,semantic+1,"no parent-wide model digest/input edge may defeat real unchanged lookup cut-off");assert_eq!(queries.db().stats(Kind(4)).computed,syntax);
 let removed="// α current offset shift\n/datum/receiver\n    var/unrelated\n/proc/probe(datum/receiver/argument)\n    return argument.field\n";std::fs::write(root.join("code/probe.dm"),removed).unwrap();run(&mut host,&request);let removed=observe(&host,&root);missing(&removed.1,removed.2);assert!(queries.db().dependants(&[global_lookup]).contains(&parent),"removing the own declaration restores the genuine global absence dependency");assert_eq!(queries.db().stats(Kind(28)).computed,semantic+2);assert_eq!(queries.db().stats(Kind(4)).computed,syntax);
 // Direct graph surgery is an intentional test fault: without the actual
 // lookup node, the model driver must have NO hidden direct edge to parent.
 let lookup_edges:Vec<_>=queries.db().dependants(&[driver]).into_iter().filter(|key|key.kind==Kind(29)).collect();assert!(lookup_edges.contains(&lookup)&&lookup_edges.contains(&global_lookup));for edge in lookup_edges{assert!(queries.db().remove(edge));}assert!(!queries.db().dependants(&[driver]).contains(&parent),"the semantic parent cannot also read a global model digest directly");let repaired=observe(&host,&root);missing(&repaired.1,repaired.2);
}
#[test]fn current_variable_actual_source_shift_rebinds_cached_findings_and_deleted_code_retracts_old_nodes(){
 let(mut host,request,root)=fixture(ABSENT);let queries=host.query_db().clone();run(&mut host,&request);let first=observe(&host,&root);missing(&first.1,first.2);let semantic=queries.db().stats(Kind(28)).computed;let syntax=queries.db().stats(Kind(4)).computed;
 let retained_old=current(&host,|snapshot|{let owner=snapshot.original_checker_request_input(&snapshot.tree).unwrap();Arc::clone(owner.input())});let code_keeper=Arc::clone(retained_old.archive().syntax_input_checked(0,&||crate::daemon::control::checkpoint()).unwrap().original_code_owner().unwrap());
 let(parent,lookup,driver)=current(&host,|snapshot|{let owner=snapshot.original_checker_request_input(&snapshot.tree).unwrap();queries.current_variable_keys_for_test(owner.input(),0,ResolveQuery::SourceVarDeclaration{owner:SymbolId::of("/datum/receiver"),name:SymbolId::of("field")})});
 let shifted=format!("/datum/unrelated\n{ABSENT}// later source-only edit\n");std::fs::write(root.join("code/probe.dm"),shifted).unwrap();run(&mut host,&request);let shifted=observe(&host,&root);missing(&shifted.1,shifted.2);assert_ne!(first.2,shifted.2);assert_eq!(queries.db().stats(Kind(28)).computed,semantic);assert_eq!(queries.db().stats(Kind(4)).computed,syntax);
 std::fs::write(root.join("code/probe.dm"),"/datum/receiver\n").unwrap();run(&mut host,&request);current(&host,|snapshot|{assert_eq!(snapshot.body_archive.as_ref().unwrap().len(),0);let mut called=false;let error=snapshot.visit_current_variable_diagnostics(0,&root.join("code/probe.dm"),None,&snapshot.tree,|_|{called=true;Ok(())}).unwrap_err();assert_eq!(error.kind(),std::io::ErrorKind::InvalidData);assert!(!called);});assert_eq!(retained_old.archive().len(),1,"a genuine old snapshot's input/archive is still physically retained");assert!(Arc::strong_count(&code_keeper)>0);assert_eq!(queries.db().value_bytes_at(parent),0,"deleted semantic membership retracts despite a held genuine old input/archive and tiny CodeID");assert!(!queries.db().dependants(&[driver]).contains(&lookup));
 std::fs::write(root.join("code/probe.dm"),ABSENT).unwrap();run(&mut host,&request);let readded=observe(&host,&root);missing(&readded.1,readded.2);assert!(queries.db().stats(Kind(28)).computed>semantic,"removed code is not resurrected from a foreign model");
}
#[test]fn current_variable_real_original_skip_is_distinct_from_unissued_grammar_and_operational_failure(){
 let(mut host,request,root)=fixture("/proc/probe()\n    return 1 +\n");run(&mut host,&request);let skipped=observe(&host,&root);assert_eq!(skipped.0,Disposition::SkippedOriginal);assert!(skipped.1.is_empty());
 let unsupported="/proc/probe(value)\n    (value)?.disassociate()\n";std::fs::write(root.join("code/probe.dm"),unsupported).unwrap();run(&mut host,&request);current(&host,|snapshot|{let mut calls=0;let error=snapshot.visit_current_variable_diagnostics(0,&root.join("code/probe.dm"),None,&snapshot.tree,|_|{calls+=1;Ok(())}).unwrap_err();println!("CURRENT_VARIABLE_UNISSUED={error:?}");assert_eq!(error.kind(),std::io::ErrorKind::Unsupported);assert_eq!(calls,0,"unissued original coverage cannot be clean success or genuine skipped code");});
 std::fs::write(root.join("code/probe.dm"),ABSENT).unwrap();run(&mut host,&request);current(&host,|snapshot|{let actual=snapshot.visit_current_variable_diagnostics(0,&root.join("code/probe.dm"),None,&snapshot.tree,|_|Err(std::io::Error::from_raw_os_error(1450))).unwrap_err();assert_eq!(actual.raw_os_error(),Some(1450));});let healthy=observe(&host,&root);missing(&healthy.1,healthy.2);assert_eq!(host.query_db().effect_graph_work_for_test(),0);
}
#[test]fn current_variable_real_existing_ledger_quota_denial_does_not_publish_empty_success_and_recovers(){
 let(mut host,request,root)=fixture(ABSENT);let queries=host.query_db().clone();run(&mut host,&request);let held=queries.effect_graph_headroom_for_test(128).unwrap();current(&host,|snapshot|{let mut calls=0;let error=snapshot.visit_current_variable_diagnostics(0,&root.join("code/probe.dm"),None,&snapshot.tree,|_|{calls+=1;Ok(())}).unwrap_err();assert_eq!(error.kind(),std::io::ErrorKind::OutOfMemory);assert_eq!(calls,0);});drop(held);assert_eq!(queries.effect_graph_work_for_test(),0);let repaired=observe(&host,&root);missing(&repaired.1,repaired.2);
}

#[test]fn current_variable_same_actual_body_producer_preserves_first_work_io_failure_without_partial_rows(){
 use dm_analysis::checker_effects::{EffectReportWork,ExecutionAdmission};use dm_analysis::policy_body_demand::PolicyFailure;
 struct Work{fail:bool,calls:usize}impl EffectReportWork for Work{type Mark=();fn reserve(&mut self,_:usize)->std::io::Result<()>{self.calls+=1;if self.fail{Err(std::io::Error::from_raw_os_error(1450))}else{Ok(())}}fn mark(&mut self)->std::io::Result<()>{Ok(())}fn reconcile(&mut self,_:(),_:usize)->std::io::Result<()>{Ok(())}}
 let(mut host,request,_)=fixture(ABSENT);run(&mut host,&request);let queries=host.query_db().clone();current(&host,|snapshot|{let archive=snapshot.body_archive.as_ref().unwrap();dm_tree::frontend::SettingExpressionQueries::with_declaration_admission(queries.as_ref(),&mut|syntax_admission|archive.with_current_body_checked(0,syntax_admission,|body|{let mut work=Work{fail:true,calls:0};let actual=dm_analysis::checks_undefined_variable::current_using(&body,body.tree(),body.tree().checker_builtin_profile().unwrap(),syntax_admission,&ExecutionAdmission::default(),&mut work,&||Ok(())).unwrap_err();assert!(matches!(actual,PolicyFailure::Operational(actual)if actual.raw_os_error()==Some(1450)));assert_eq!(work.calls,1,"first actual storage refusal stops before local maps/output allocations");Ok(())})).unwrap();});
}


#[test]fn current_selected_prelude_and_body_share_one_semantic_node_and_rebind_presentation_without_reevaluation(){
 use crate::query_db::CurrentSelectedDiagnostic as Selected;
 const SOURCE:&str="/datum/receiver\n/proc/probe(datum/receiver/argument)\n    set SpacemanDMM_should_not_sleep = 2\n    return argument.field\n";
 let(mut host,request,root)=fixture(SOURCE);let queries=host.query_db().clone();run(&mut host,&request);
 let observe=|host:&crate::runner_host::BuildHost|current(host,|snapshot|{let mut rows=Vec::new();let result=snapshot.visit_current_selected_diagnostics(0,&root.join("code/probe.dm"),None,&snapshot.tree,|row|{match row{Selected::Prelude(row)=>rows.push((0,row.span.start,row.message.clone())),Selected::Body(row)=>rows.push((1,row.span.start,row.diagnostic.message.clone()))}Ok(())}).unwrap();assert_eq!(result,Disposition::Evaluated);rows});
 let first=observe(&host);println!("CURRENT_SELECTED_FIRST={first:?}");assert_eq!(first.len(),2);assert_eq!((first[0].0,first[1].0),(0,1));assert!(first[0].2.contains("line: 3, column: 40"));assert_eq!(first[1].2,"undefined field: \"field\" on /datum/receiver");let semantic=queries.db().stats(Kind(28)).computed;let syntax=queries.db().stats(Kind(4)).computed;
 // The existing variable-only consumer borrows this same retained contribution.
 let variables=current(&host,|snapshot|{let mut rows=Vec::new();snapshot.visit_current_variable_diagnostics(0,&root.join("code/probe.dm"),None,&snapshot.tree,|row|{rows.push(row.diagnostic.message.clone());Ok(())}).unwrap();rows});assert_eq!(variables.len(),1);assert_eq!(queries.db().stats(Kind(28)).computed,semantic);
 std::fs::write(root.join("code/probe.dm"),format!("/datum/unrelated\n{SOURCE}")).unwrap();run(&mut host,&request);let shifted=observe(&host);println!("CURRENT_SELECTED_SHIFTED={shifted:?}");assert_eq!(shifted.len(),2);assert!(shifted[0].2.contains("line: 4, column: 40"));assert_ne!(first[0].2,shifted[0].2,"real current Debug location, not stale retained physical message");assert_ne!(first[1].1,shifted[1].1);assert_eq!(queries.db().stats(Kind(28)).computed,semantic,"presentation-only change cannot rerun the same semantic node");assert_eq!(queries.db().stats(Kind(4)).computed,syntax,"both consumers borrow same canonical syntax");
 let present=SOURCE.replace("/datum/receiver\n","/datum/receiver\n    var/field\n");std::fs::write(root.join("code/probe.dm"),present).unwrap();run(&mut host,&request);let added=observe(&host);assert_eq!(added.len(),1);assert_eq!(added[0].0,0);assert_eq!(queries.db().stats(Kind(28)).computed,semantic+1,"actual negative declaration becoming positive reevaluates one shared contribution");assert_eq!(queries.db().stats(Kind(4)).computed,syntax);
 current(&host,|snapshot|{let actual=snapshot.visit_current_selected_diagnostics(0,&root.join("code/probe.dm"),None,&snapshot.tree,|_|Err(std::io::Error::from_raw_os_error(1450))).unwrap_err();assert_eq!(actual.raw_os_error(),Some(1450));});assert_eq!(queries.effect_graph_work_for_test(),0,"temporary Debug message/report escrow must unwind on actual consumer failure");assert_eq!(observe(&host).len(),1);
}

#[test]fn current_variable_initialized_native_metadata_uses_admitted_encoder_and_reuses_unchanged_body(){
 const INITIAL:&str="/datum/receiver\n/proc/probe(datum/receiver/argument)\n    return argument.field\n";
 let(mut host,request,root)=fixture(INITIAL);let queries=host.query_db().clone();run(&mut host,&request);let first=observe(&host,&root);missing(&first.1,first.2);let syntax=queries.db().stats(Kind(4)).computed;let semantic=queries.db().stats(Kind(28)).computed;
 for(index,default)in ["1","2"].into_iter().enumerate(){let source=INITIAL.replace("/datum/receiver\n",&format!("/datum/receiver\n    var/field = {default}\n"));std::fs::write(root.join("code/probe.dm"),source).unwrap();run(&mut host,&request);let actual=observe(&host,&root);assert_eq!(actual.0,Disposition::Evaluated);assert!(actual.1.is_empty());assert_eq!(queries.db().stats(Kind(4)).computed,syntax,"initialized field edits preserve actual canonical BODY owner");assert_eq!(queries.db().stats(Kind(28)).computed,semantic+index as u64+1,"exact native metadata answer changes invalidate the existing semantic node");}
 std::fs::write(root.join("code/probe.dm"),INITIAL).unwrap();run(&mut host,&request);let removed=observe(&host,&root);missing(&removed.1,removed.2);assert_eq!(queries.db().stats(Kind(4)).computed,syntax);assert_eq!(queries.effect_graph_work_for_test(),0,"all temporary native serialization funding retires");
}

#[test]fn current_variable_original_qualifier_fact_is_authenticated_in_existing_native_leaf_and_retracts(){
 const PREFIX:&str="/datum/target\n/datum/receiver\n";
 const TAIL:&str="/proc/probe(datum/receiver/argument)\n    return argument.field\n";
 let source=|qualifier:&str|format!("{PREFIX}    var/{qualifier}datum/target/field\n{TAIL}");
 let(mut host,request,root)=fixture(&source(""));let queries=host.query_db().clone();run(&mut host,&request);assert!(observe(&host,&root).1.is_empty());let semantic=queries.db().stats(Kind(28)).computed;let syntax=queries.db().stats(Kind(4)).computed;
 let actual=|host:&crate::runner_host::BuildHost|current(host,|snapshot|{let owner=snapshot.original_checker_request_input(&snapshot.tree).unwrap();queries.current_variable_actual_property_for_test(owner.input(),SymbolId::of("/datum/receiver"),SymbolId::of("field")).unwrap()});assert_eq!(actual(&host),0);
 let(parent,lookup,_)=current(&host,|snapshot|{let owner=snapshot.original_checker_request_input(&snapshot.tree).unwrap();queries.current_variable_keys_for_test(owner.input(),0,ResolveQuery::SourceVarDeclaration{owner:SymbolId::of("/datum/receiver"),name:SymbolId::of("field")})});assert!(queries.db().dependants(&[lookup]).contains(&parent));
 for(index,(qualifier,flags))in [("SpacemanDMM_private/",dm_syntax::CHECKER_VAR_PRIVATE),("SpacemanDMM_protected/",dm_syntax::CHECKER_VAR_PROTECTED),("",0)].into_iter().enumerate(){std::fs::write(root.join("code/probe.dm"),source(qualifier)).unwrap();run(&mut host,&request);assert!(observe(&host,&root).1.is_empty());assert_eq!(actual(&host),flags);assert_eq!(queries.db().stats(Kind(4)).computed,syntax);assert_eq!(queries.db().stats(Kind(28)).computed,semantic+index as u64+1,"selected authentic property change invalidates SAME semantic contribution");}
 let stable=queries.db().stats(Kind(28)).computed;std::fs::write(root.join("code/probe.dm"),format!("// α source shift\n{}",source(""))).unwrap();run(&mut host,&request);assert!(observe(&host,&root).1.is_empty());assert_eq!(actual(&host),0);assert_eq!(queries.db().stats(Kind(28)).computed,stable,"no coordinate/header-wide source dependency on the parent");assert_eq!(queries.db().stats(Kind(4)).computed,syntax);
 current(&host,|snapshot|{let owner=snapshot.original_checker_request_input(&snapshot.tree).unwrap();let archive=owner.input().archive();let formal=archive.tree().source_formal_variable_member(SymbolId::of("/datum/receiver"),SymbolId::of("field")).unwrap().unwrap();let foreign=dm_ir::PackedU128::new(owner.input().profile().get()^1);assert_eq!(archive.checker_variable_qualifiers_admitted(formal,foreign).unwrap_err().kind(),std::io::ErrorKind::Unsupported,"a foreign profile cannot issue zero/guessed source flags");});
 std::fs::write(root.join("code/probe.dm"),format!("{PREFIX}{TAIL}")).unwrap();run(&mut host,&request);let missing=observe(&host,&root);assert_eq!(missing.1.len(),1);assert_eq!(missing.1[0].2,"undefined field: \"field\" on /datum/receiver");assert_eq!(queries.db().stats(Kind(4)).computed,syntax);assert!(queries.db().dependants(&[lookup]).contains(&parent),"actual missing source leaf remains a real dependency after qualifier removal");assert_eq!(queries.effect_graph_work_for_test(),0);
}
